select s.id
from gc_user_save_content u
left join gc_subject s on s.id = u.sub_id

    1=1

        and u.user_id = #{entity.userId}


        and u.master_id = #{entity.masterId}


        and u.folder_id = #{entity.folderId}

        and s.fid is not null
        and u.sub_id is not null

select s.id
from gc_user_save_content u
left join gc_subject s on s.id = u.sub_id

    1=1

        and u.user_id = #{entity.userId}


        and u.master_id = #{entity.masterId}


        and u.folder_id = #{entity.folderId}

    and s.fid is null
    and u.sub_id is not null

select gusc.content_id
from gc_user_save_content gusc

1=1

        and gusc.folder_id = #{entity.folderId}


        and gusc.master_id = #{entity.masterId}


order by gusc.create_time asc

select gusc.id
from gc_user_save_content gusc
    JOIN  course_content cc ON cc.content_id = gusc.content_id
    JOIN gc_video gv ON gv.id = cc.content_id AND gv.id = #{videoId}

and folder_id in

    #{folderId}

select gusc.folder_id
from gc_user_save_content gusc
     JOIN  course_content cc ON cc.content_id = gusc.content_id
     JOIN gc_video gv ON gv.id = cc.content_id AND gv.id = #{videoId}
where master_id = #{masterId}

select gusc.folder_id
from gc_user_save_content gusc
    JOIN gc_video gv ON gv.id = gusc.content_id AND gv.file_id = #{fileId}
where gusc.master_id = #{masterId}

select , , ,
FROM gc_user_save_content playlist_content JOIN gc_video video ON video.id = playlist_content.content_id JOIN sys_file video_file ON video.file_id = video_file.id
LEFT JOIN pt_channel channel on channel.id = video.origin_channel_id LEFT JOIN gc_subject course on course.id = video.origin_course_id WHERE playlist_content.folder_id = #{playlistId}

select gusc.id
from gc_user_save_content gusc
    JOIN gc_video gv ON gv.id = gusc.content_id
where gv.file_id = #{fileId}

    and gusc.folder_id in

        #{folderId}
